            };

            let use_pager = match matches.get_one::<String>("paging").map(|s| s.as_str()) {
                Some("never") => false,
                _ => !matches.get_flag("no-paging"),
            };

            let use_color = match matches.get_one::<String>("color").map(|s| s.as_str()) {
                Some("always") => true,
